from rcb_client import Robot
import numpy as np
r=Robot();o=r.get_obs(video='none',depth=True); im=o.last['scene_cam'];d=o.last_depth['scene_cam'];
for u,v in [(285,217),(285,220),(288,216),(280,215),(300,220),(320,200)]: print((u,v),im[v,u].tolist(),d[v,u])
# deproject candidate using extrinsic inverse
E=np.array(o.meta['cameras']['scene_cam']['extrinsic_cv']);K=np.array(o.meta['cameras']['scene_cam']['intrinsic_cv']);
for u,v in [(285,217),(288,216),(300,220),(320,200)]:
 z=d[v,u]; ray=np.linalg.inv(K)@np.array([u,v,1.]); cv=ray*z; w=np.linalg.inv(np.vstack([np.c_[E,[0,0,0]], [0,0,0,1]]))@np.r_[cv,1];print('world',u,v,z,w[:3])
